SELECT TOP 100 "BEAS_MRP_DETAIL"."ItemCode","BEAS_MRP_DETAIL"."POS","BEAS_MRP_DETAIL"."ART", "BEAS_MRP_DETAIL"."DATUM" as 'DOC Date',"BEAS_MRP_DETAIL"."Name","BEAS_MRP_DETAIL"."INFO","BEAS_MRP_DETAIL"."BELNR_ID","BEAS_MRP_DETAIL"."BELPOS_ID","BEAS_MRP_DETAIL"."POS_ID","BEAS_MRP_DETAIL"."DocType","BEAS_MRP_DETAIL"."DocEntry","BEAS_MRP_DETAIL"."LineNum",	 "BEAS_MRP_DETAIL"."OnHand",	 coalesce("FERTIGUNG_ZUGANG",0)+coalesce("BESTELLUNG_ZUGANG",0) AS 'IN',	  coalesce("FERTIGUNG_ABGANG",0)+coalesce("AUFTRAG_ABGANG",0) AS 'OUT',	 	   	    "BEAS_MRP_DETAIL"."ONHAND2" as 'Balance',		coalesce("FERTIGUNG_ABGANG",0)+coalesce("AUFTRAG_ABGANG",0) - coalesce("BEAS_MRP_DETAIL"."RESERVATION",0) AS 'Reservation',		"BEAS_MRP_DETAIL"."INFO2",		 "BEAS_MRP_DETAIL"."TABLEREF",		  "BEAS_MRP_DETAIL"."Project",		   "BEAS_MRP_DETAIL"."BEWERTET",		    "BEAS_MRP_DETAIL"."INFOTEXT","BEAS_MRP_DETAIL"."Version","BEAS_MRP_DETAIL"."ZNR","BEAS_MRP_DETAIL"."BEDARFSDATUM", "BEAS_MRP_DETAIL"."VRI", "BEAS_MRP_DETAIL"."SHORTVARIANT", "BEAS_MRP_DETAIL"."INFO3", "BEAS_MRP_DETAIL"."COLORNR", "BEAS_MRP_DETAIL"."RESERVATION", "BEAS_MRP_DETAIL"."UID", "BEAS_MRP_DETAIL"."RELEASED", "BEAS_MRP_DETAIL"."Linked", "BEAS_MRP_DETAIL"."DEMANDCOVERING", "BEAS_MRP_DETAIL"."WhsCode", "BEAS_MRP_DETAIL"."PRJUID","OITM"."InvntryUom", "BEAS_PRJ_LINE"."DESCRIPTION" ,substring(convert(varchar(20),"BEAS_KALENDER"."KW_ID"),5,2) as "KW", case when "BEAS_MRP_DETAIL"."ART"='B' then "POR1"."U_beas_requestdel" else "RDR1"."U_beas_requestdel" end as rdr1_u_beas_requestdel,case when "BEAS_MRP_DETAIL"."ART"='B' then "POR1"."U_beas_delconfirm" else "RDR1"."U_beas_delconfirm" end as rdr1_u_beas_delconfirmFROM "BEAS_MRP_DETAIL" LEFT OUTER JOIN "OITM" on "OITM"."ItemCode"="BEAS_MRP_DETAIL"."ItemCode"LEFT OUTER JOIN "BEAS_PRJ_LINE" ON "BEAS_MRP_DETAIL"."Project" = "BEAS_PRJ_LINE"."PrjCode" AND "BEAS_MRP_DETAIL"."PRJUID" = "BEAS_PRJ_LINE"."PRJUID"LEFT OUTER JOIN "RDR1" on "RDR1"."DocEntry"="BEAS_MRP_DETAIL"."DocEntry" and "BEAS_MRP_DETAIL"."LineNum"="RDR1"."LineNum" and "BEAS_MRP_DETAIL"."ART" in ('A','S')LEFT OUTER JOIN "POR1" on "POR1"."DocEntry"="BEAS_MRP_DETAIL"."DocEntry" and "BEAS_MRP_DETAIL"."LineNum"="POR1"."LineNum" and "BEAS_MRP_DETAIL"."ART" = 'B'LEFT OUTER JOIN "BEAS_KALENDER" ON convert(varchar(10),"BEAS_KALENDER"."DATUM_ID",112) = convert(varchar(10),"BEAS_MRP_DETAIL"."BEDARFSDATUM",112)WHERE "BEAS_MRP_DETAIL"."NR" = @MRP AND "BEAS_MRP_DETAIL"."ItemCode" = @itemcode AND (case when "OITM"."ManBtchNum"='Y' OR "OITM"."ManSerNum"='Y' THEN (case when "BEAS_MRP_DETAIL"."Version" = '' then 1 else 0 end) ELSE 1 END)=1ORDER BY "BEAS_MRP_DETAIL"."NR", "BEAS_MRP_DETAIL"."POS"